/* Promotional simulation of the Home routes at consolidated V5 2ab7570.
   Fixture data only. No API, uploads, AI calls or real permission changes. */
money = n => new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const V5 = {
  workflow: 'Tutti', family: 'Tutte le famiglie', query: '', objectQuery: '',
  room: 'Tutte le stanze', objectState: 'Attivi', activityTab: 'Scadenze',
  activityState: 'Aperte', expenseTab: 'Registrazioni', expenseQuery: '',
  contactQuery: '', roomQuery: '', year: 'Tutti', form: null,
  documents: [
    {id:'manual',name:'Manuale lavastoviglie',family:'Acquisti, garanzie e manuali',status:'Completato',object:'Lavastoviglie',personal:true},
    {id:'invoice',name:'Fattura manutenzione caldaia',family:'Energia e impianti',status:'Completato',object:'Caldaia',personal:true},
    {id:'plan',name:'Planimetria della casa',family:'Catasto e pratiche edilizie',status:'Completato',object:'',personal:true},
    {id:'purchase',name:'Fattura acquisto demo',family:'Da classificare',status:'Da compilare',object:'',personal:true},
    {id:'bill',name:'Bolletta luce demo',family:'Da classificare',status:'Da compilare',object:'',personal:true}
  ],
  objects: [
    {id:'dish',name:'Lavastoviglie',brand:'Bosch',model:'Modello dimostrativo',room:'Cucina',type:'Elettrodomestico',archived:false,warranty:'Da verificare',doc:'manual',cost:650},
    {id:'boiler',name:'Caldaia',brand:'Vaillant',model:'Modello dimostrativo',room:'Locale tecnico',type:'Impianto',archived:false,warranty:'Da verificare',doc:'invoice',cost:0}
  ],
  rooms:['Cucina','Soggiorno','Camera','Locale tecnico'],
  contacts:[{id:'tech',name:'Tecnico Demo',email:'tecnico@example.test',role:'Manutenzione',archived:false},{id:'seller',name:'Rivenditore Demo',email:'rivenditore@example.test',role:'Acquisti',archived:false}],
  tasks:[{id:'maint',name:'Manutenzione caldaia',date:'2026-11-05',object:'boiler',done:false,next:''}],
  expenses:[{id:'cost1',name:'Manutenzione caldaia',amount:120,date:'2026-10-12',supplier:'Tecnico Demo',object:'boiler',doc:'invoice',paid:false,work:''}],
  history:[{id:'event1',title:'Manutenzione caldaia',date:'2026-10-12',doc:'invoice',kind:'Intervento'}],
  works:[],shares:[], counter:10
};
const FAMILIES=['Proprietà e affitto','Catasto e pratiche edilizie','Energia e impianti','Condominio','Utenze e servizi','Lavori, ristrutturazioni e bonus','Tasse e tributi','Assicurazioni','Acquisti, garanzie e manuali','Sicurezza e vincoli','Da classificare'];
const PRIMARY=['Casa','Oggetti e impianti','Ambienti','Attività','Documenti','Spese','Rubrica'];
roles.home.nav=[...PRIMARY,'Storia della casa','Condivisioni','Scenari di spesa','Condominio','Piano e preferenze'];
roles.home.journey=['Casa','Documenti','Oggetti e impianti','Ambienti','Attività','Spese','Rubrica'];
const originalPageContent=pageContent, originalDashboard=dashboard, originalWorkspace=workspace;
const vButton=(label,action,light=false)=>button(label,'v5:'+action,light);
const vRow=(title,sub,action,label='Apri',icon='▤')=>row(title,sub,action?'v5:'+action:null,label,icon);
const vEmpty=t=>`<div class="empty">${esc(t)}</div>`;
const vOptions=(values,current)=>values.map(t=>`<option ${t===current?'selected':''}>${esc(t)}</option>`).join('');
const vSelect=(label,id,values,value)=>`<div class="v5-control"><label for="${id}">${label}</label><select id="${id}">${vOptions(values,value)}</select></div>`;
const vField=(label,id,value='',type='text')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">`;
const vDate=d=>d?d.split('-').reverse().join('/'):'Senza data';
const vId=()=>String(++V5.counter);
function vTabs(label,values,current,key){return `<div class="filter" role="group" aria-label="${label}">${values.map(t=>`<button aria-pressed="${t===current}" class="${t===current?'active':''}" data-action="v5:tab:${key}:${t}">${t}</button>`).join('')}</div>`;}
function vSearch(label,id,value){return `<div class="v5-search"><label for="${id}">${label}</label><input type="search" id="${id}" value="${esc(value)}" placeholder="${label}"></div>`;}
function vRefresh(){render();if(V5.form)vEditor();}
function vError(t){let target=$('#v5-error');if(!target){target=document.createElement('p');target.id='v5-error';target.setAttribute('role','alert');$('#modal').append(target);}target.textContent=t;}
function vModal(title,body,actions){modal(title,body,actions);$('#dialog').setAttribute('aria-label',title);}
function vFixtureDocument(d){return `<div class="v5-original"><div class="eyebrow">Facsimile · dati di esempio</div><h3>${esc(d.name)}</h3><p>Immobile: ${esc(state.selected)}</p><hr><p>Documento originale rappresentato in anteprima.<br>Fonte: archivio personale · versione 1.</p><p>${d.id==='bill'?'Fornitura elettrica · periodo settembre 2026 · totale € 86,40':d.id==='purchase'?'Rivenditore Demo · macchina da caffè · importo € 499,00':d.id==='plan'?'Cucina, soggiorno, camera, locale tecnico. Nessuna superficie dedotta.':'Informazioni dimostrative collegate alla casa.'}</p><p class="tiny">Questo facsimile non è un file personale.</p></div>`;}
function vDocument(id){const d=V5.documents.find(x=>x.id===id);if(!d)return;vModal(d.name,`${vFixtureDocument(d)}<div class="v5-inline-meta">${pill(d.status)} ${pill(d.family)}</div><p class="tiny">Visibile solo a te · Fonte e versione conservate</p>`,vButton(d.status==='Completato'?'Rivedi i dati':'Compila','compile:'+id)+vButton('Scarica facsimile','download:'+id,true)+vButton('Aggiungi alla storia','event:'+id,true)+(d.status==='Completato'?vButton('Cambia famiglia','family:'+id,true):'')+vButton('Elimina documento','delete:'+id,true));}
function vDocuments(){const list=V5.documents.filter(d=>(V5.workflow==='Tutti'||(V5.workflow==='Da fare'?d.status!=='Completato':d.status==='Completato'))&&(V5.family==='Tutte le famiglie'||d.family===V5.family)&&d.name.toLowerCase().includes(V5.query.toLowerCase()));return `<p class="v5-lead">Conserva i file. Completa i dati. Ritrova tutto collegato.</p><div class="v5-actions">${vButton('Aggiungi documento','import')}${vButton('Compila i documenti da fare','next-pending',true)}</div>${vTabs('Stato dei documenti',['Tutti','Da fare','Completati'],V5.workflow,'workflow')}<div class="v5-filters">${vSearch('Cerca un documento','v5-doc-search',V5.query)}${vSelect('Famiglia','v5-family',['Tutte le famiglie',...FAMILIES],V5.family)}</div>${card('Archivio documenti',list.map(d=>`<div class="row"><div class="row-icon">▤</div><div class="rowbody"><strong>${esc(d.name)}</strong><p>${esc(d.family)} · Originale v1 · Visibile solo a te</p><span class="v5-status ${d.status==='Completato'?'complete':''}">${d.status}</span></div>${vButton(d.status==='Completato'?'Apri':'Compila',(d.status==='Completato'?'document:':'compile:')+d.id,true)}</div>`).join('')||vEmpty('Nessun documento con questi filtri.'))}<p class="tiny">La ricerca e i dati sono dimostrativi. Nell’app le analisi dipendono da disponibilità, autorizzazioni e documento.</p>`;}
dashboard=function(){if(state.role!=='home')return originalDashboard();const pending=V5.documents.filter(d=>d.status!=='Completato').length,open=V5.tasks.filter(t=>!t.done).length;return `<div class="v5-actions">${vButton('Aggiungi documento','import')}${vButton('Registra una spesa','expense-new',true)}</div>${metrics([['Da completare',pending,'Documenti da compilare'],['Scadenze',open,'Attività personali aperte'],['Spese registrate',money(V5.expenses.reduce((a,x)=>a+x.amount,0)),'Importi di esempio']])}<div class="columns">${card('Esplora la casa',row('Oggetti e impianti','Elettrodomestici, impianti e altri oggetti','nav:Oggetti e impianti','Esplora','▦')+row('Ambienti','Le stanze della casa','nav:Ambienti','Esplora','▧')+row('Documenti della casa','Planimetrie, APE, pratiche e contratti','nav:Documenti','Esplora','▤')+row('Storia della casa','Lavori, interventi ed eventi nel tempo','nav:Storia della casa','Esplora','◷'))}${card('Le prossime scadenze',V5.tasks.filter(t=>!t.done).slice(0,3).map(t=>vRow(t.name,vDate(t.date),'task:'+t.id,'Apri','◷')).join('')||vEmpty('Nessuna attività aperta.'))}</div><div class="banner"><div><h3>La memoria cresce un documento alla volta.</h3><p>${pending?pending+' documenti pronti per una compilazione dimostrativa.':'Hai completato i documenti di questa demo.'} Scegli tu cosa registrare.</p></div>${vButton('Completa i dati →','next-pending',true)}</div><p class="tiny">Come nella V5: oggetti e spese personali, ambienti condivisi. Dati e permessi qui sono solo simulati.</p>`;};
function vObjects(){let list=V5.objects.filter(o=>o.archived===(V5.objectState==='Archiviati')&&(V5.room==='Tutte le stanze'||(V5.room==='Senza stanza'?!o.room:o.room===V5.room))&&(o.name+' '+o.brand+' '+o.model).toLowerCase().includes(V5.objectQuery.toLowerCase()));return `<div class="v5-actions">${vButton('Aggiungi oggetto','object-new')}</div><div class="v5-filters">${vSearch('Cerca nome, marca o modello','v5-object-search',V5.objectQuery)}${vSelect('Stanza','v5-room-filter',['Tutte le stanze','Senza stanza',...V5.rooms],V5.room)}${vSelect('Stato','v5-object-state',['Attivi','Archiviati'],V5.objectState)}</div><div class="gridcards">${list.map(o=>card(`<div class="bigicon">${o.type==='Impianto'?'♧':'▦'}</div>${esc(o.name)}`,`<p>${esc(o.brand)} · ${esc(o.room||'Senza stanza')}</p><span class="pill">${esc(o.type)} · Solo tu</span><div class="actions">${vButton('Apri scheda →','object:'+o.id,true)}</div>`)).join('')||vEmpty('Nessun oggetto con questi filtri.')}</div>`;}
function vObject(id){const o=V5.objects.find(x=>x.id===id);if(!o)return;const cost=V5.expenses.filter(e=>e.object===id).reduce((a,e)=>a+e.amount,0);vModal(o.name,`<p>${esc(o.type)} · Visibile solo a te${o.archived?' · Archiviato':''}</p><div class="v5-detail-summary"><div><small>Dove si trova</small><strong>${esc(o.room||'Senza stanza')}</strong></div><div><small>Garanzia</small><strong>${esc(o.warranty)}</strong></div></div><p>${esc(o.brand)} · ${esc(o.model)}</p>${(o.documents||[o.doc]).filter(Boolean).map(doc=>vRow('Documenti e manuali',V5.documents.find(d=>d.id===doc)?.name||'Fonte collegata','document:'+doc,'Consulta')).join('')||'<p>Nessun documento collegato.</p>'}${vRow('Spese collegate',money(cost)+' registrati','object-expenses:'+id,'Apri','€')}${vRow('Attività',V5.tasks.filter(t=>t.object===id).length+' collegate','task-new:'+id,'Aggiungi','◷')}${vRow('Contatti','Collegamenti personali','contacts','Rubrica','♧')}<details><summary>Storia dell’oggetto</summary><p>Oggetto dimostrativo inserito nella casa. Posizione e collegamenti sono mantenuti.</p></details>`,vButton('Nome e tipo','object-edit:'+id)+vButton('Dati e garanzia','warranty:'+id,true)+vButton('Sposta in un ambiente','placement:'+id,true)+vButton(o.archived?'Ripristina':'Archivia','object-archive:'+id,true));}
function vRooms(){let rooms=V5.rooms.filter(n=>n.toLowerCase().includes(V5.roomQuery.toLowerCase()));return `<div class="v5-actions">${vButton('Aggiungi ambiente','room-new')}${vButton('Da planimetria','floorplan',true)}</div>${vSearch('Cerca un ambiente','v5-room-search',V5.roomQuery)}<div class="gridcards">${rooms.map(n=>card(esc(n),`<p>${V5.objects.filter(o=>o.room===n&&!o.archived).length} oggetti · Ambiente condiviso</p>${vButton('Esplora ambiente →','room:'+n,true)}`)).join('')||vEmpty('Nessun ambiente trovato.')}</div>`;}
function vRoom(name){vModal(name,`<p>Ambiente condiviso · Oggetti personali</p>${V5.objects.filter(o=>o.room===name&&!o.archived).map(o=>vRow(o.name,o.type+' · visibile solo a te','object:'+o.id,'Apri','▦')).join('')||'<p>Non hai ancora collocato oggetti in questo ambiente.</p>'}`,vButton('Aggiungi oggetto','object-new:'+name)+vButton('Modifica ambiente','room-edit:'+name,true));}
function vActivities(){let list=V5.tasks.filter(t=>V5.activityState==='Tutte'||(V5.activityState==='Completate'?t.done:!t.done));return `<div class="v5-actions">${vButton('Nuova attività','task-new')}</div>${vTabs('Viste delle attività',['Scadenze','Analisi e verifiche'],V5.activityTab,'activityTab')}${V5.activityTab==='Scadenze'?`${vTabs('Stato attività',['Aperte','Completate','Tutte'],V5.activityState,'activityState')}${card('Scadenze personali',list.map(t=>vRow(t.name,vDate(t.date)+' · '+(t.done?'Completata':'In programma'),'task:'+t.id,'Apri','◷')).join('')||vEmpty('Nessuna attività in questa vista.'))}`:card('Analisi e verifiche','<p>Rivedi i dati proposti prima di confermarli. Non sono verifiche di conformità.</p>'+V5.documents.filter(d=>d.status!=='Completato').map(d=>vRow(d.name,'Documento da compilare · nessuna analisi reale','compile:'+d.id,'Rivedi')).join('')+vButton('Scegli documento per una proposta AI','analysis',true))}`;}
function vTask(id){const t=V5.tasks.find(x=>x.id===id);if(!t)return;vModal(t.name,`<p>${t.done?'Completata':'In programma'} · ${vDate(t.date)}</p><p>Oggetto: ${esc(V5.objects.find(o=>o.id===t.object)?.name||'Casa')}</p>${t.done?'<p>Prossimo promemoria: '+vDate(t.next)+'</p>':vField('Data completamento','v5-completed','2026-10-24','date')+vField('Prossimo promemoria (facoltativo)','v5-next','','date')}<p class="tiny">Il prossimo promemoria viene creato solo se scegli una data.</p>`,t.done?vButton('Chiudi','close',true):vButton('Completa attività','task-done:'+id));}
function vExpenses(){let list=V5.expenses.filter(e=>(e.name+' '+e.supplier).toLowerCase().includes(V5.expenseQuery.toLowerCase()));let total=list.reduce((a,e)=>a+e.amount,0);return `<div class="v5-actions">${vButton('Registra una spesa','expense-new')}${vButton('Da documento','import',true)}${vButton('Lavori','works',true)}</div>${vTabs('Viste delle spese',['Registrazioni','Riepilogo'],V5.expenseTab,'expenseTab')}${V5.expenseTab==='Registrazioni'?`${vSearch('Cerca in descrizione o fornitore','v5-expense-search',V5.expenseQuery)}${card('Costi registrati',list.map(e=>vRow(e.name,vDate(e.date)+' · '+money(e.amount)+' · '+e.supplier,'expense:'+e.id,'Apri','€')).join('')||vEmpty('Nessuna spesa con questa ricerca.'))}`:`${metrics([['Totale registrato',money(total),'Spese dimostrative'],['Registrazioni',list.length,'Con descrizione e fonte'],['Da verificare',list.filter(e=>!e.paid).length,'Pagamento non dichiarato']])}${card('Spese per oggetto',V5.objects.map(o=>vRow(o.name,money(V5.expenses.filter(e=>e.object===o.id).reduce((a,e)=>a+e.amount,0)),'object-expenses:'+o.id,'Dettagli','▦')).join(''))}`}<p class="tiny">L’app separa spese registrate, oggetti e lavori. Le previsioni a cinque anni sono nella sezione «Anteprime di prodotto».</p>`;}
function vExpense(id){const e=V5.expenses.find(x=>x.id===id);if(!e)return;vModal(e.name,`<div class="v5-detail-summary"><div><small>Importo</small><strong>${money(e.amount)}</strong></div><div><small>Data</small><strong>${vDate(e.date)}</strong></div></div><p>Fornitore: ${esc(e.supplier||'Non indicato')}<br>Pagamento: ${e.paid?'Dichiarato nella demo':'Non dichiarato'}<br>Oggetto: ${esc(V5.objects.find(o=>o.id===e.object)?.name||'Spesa della casa')}</p>${e.doc?vRow('Documento fonte',V5.documents.find(d=>d.id===e.doc)?.name||'Documento','document:'+e.doc,'Apri'):''}`,vButton('Modifica spesa','expense-edit:'+id)+vButton('Chiudi','close',true));}
function vContacts(){const list=V5.contacts.filter(c=>!c.archived&&(c.name+' '+c.role).toLowerCase().includes(V5.contactQuery.toLowerCase()));return `<p class="v5-lead">I contatti per questa casa, visibili solo a te.</p><div class="v5-actions">${vButton('Nuovo contatto','contact-new')}</div>${vSearch('Cerca un contatto','v5-contact-search',V5.contactQuery)}${card('Rubrica',list.map(c=>vRow(c.name,c.role+' · '+c.email,'contact:'+c.id,'Apri','♧')).join('')||vEmpty('Nessun contatto trovato.'))}<details class="card"><summary>Contatti archiviati</summary>${V5.contacts.filter(c=>c.archived).map(c=>vRow(c.name,c.role,'contact:'+c.id,'Apri')).join('')||'<p>Nessun contatto archiviato.</p>'}</details>`;}
function vContact(id){const c=V5.contacts.find(x=>x.id===id);if(!c)return;vModal(c.name,`<p>${esc(c.role)} · Visibile solo a te</p><p>${esc(c.email||'Email non indicata')}</p>${vRow('Collegamenti','Oggetti, spese e documenti personali','contact-links:'+id,'Consulta')}<p class="tiny">L’archiviazione mantiene i collegamenti; non invia messaggi.</p>`,vButton('Modifica contatto','contact-edit:'+id)+vButton(c.archived?'Ripristina contatto':'Archivia contatto','contact-archive:'+id,true));}
function vHistory(){const years=['Tutti',...new Set(V5.history.map(e=>e.date.slice(0,4)))].sort((a,b)=>a==='Tutti'?-1:b.localeCompare(a));return `<p class="v5-lead">Gli eventi che inserisci tu, i lavori, i promemoria completati e gli oggetti aggiunti. Visibile solo a te.</p><div class="v5-actions">${vButton('+ Aggiungi un evento','event')}</div>${vTabs('Filtra per anno',years,V5.year,'year')}${card('La storia della casa',V5.history.filter(e=>V5.year==='Tutti'||e.date.startsWith(V5.year)).map(e=>vRow(e.title,vDate(e.date)+' · '+e.kind,e.doc?'document:'+e.doc:'event-detail:'+e.id,e.doc?'Fonte':'Apri','◷')).join('')||vEmpty('Nessun evento in questo anno.'))}`;}
pageContent=function(){if(state.role!=='home')return `<div class="v5-concept"><strong>Anteprima di prodotto · ${roles[state.role].name}</strong><p>Questo profilo riprende il mockup Partner. Non ha ancora schermate operative nella V5 consolidata.</p></div>`+originalPageContent();switch(state.page){case'Casa':return dashboard();case'Documenti':return vDocuments();case'Oggetti e impianti':return vObjects();case'Ambienti':return vRooms();case'Attività':return vActivities();case'Spese':return vExpenses();case'Rubrica':return vContacts();case'Storia della casa':return vHistory();case'Condivisioni':return card('Condivisioni selettive','<p>Scegli i documenti, controlla i diritti e prepara una consegna. Il destinatario deve accettarla.</p>'+vButton('Nuova condivisione','sharing'))+card('Le consegne demo',V5.shares.map(s=>vRow(s.email,s.names.join(' · ')+' · '+s.status,'share-detail:'+s.id,'Dettagli')).join('')||'<p>Nessuna consegna preparata.</p>');case'Scenari di spesa':return '<div class="v5-concept"><strong>Anteprima di prodotto</strong><p>Lo scenario economico del mockup non è una schermata della V5 operativa.</p></div>'+forecast(false);case'Condominio':case'Piano e preferenze':return '<div class="v5-concept"><strong>Anteprima di prodotto</strong><p>Questa esperienza appartiene al concept Home/Partner; non equivale a una funzione già disponibile nella V5.</p></div>'+originalPageContent();default:return originalPageContent();}};
workspace=function(){let html=originalWorkspace();html=html.replaceAll('undefined &nbsp;','↗ &nbsp;');html=html.replace('↗ &nbsp; Scenari di spesa','↗ &nbsp; Scenari di spesa · concept');html=html.replace(/(<button class="navitem[^>]*data-action="nav:Scenari di spesa")/,'<div class="nav-extra">Anteprime di prodotto</div>$1');html=html.replace('Esplora anche · demo','Altri percorsi della casa');html=html.replace('Una vista semplice. I dettagli quando ti servono.',state.role==='home'?'La stessa organizzazione della V5, con esempi da esplorare.':'Il percorso Partner, in anteprima.');html=html.replace('<h1>Tutto quello che chiami casa.</h1>',`<h1>${esc(state.selected)}</h1>`);html=html.replace(/<button class="btn " data-action="import">\+ Aggiungi<\/button>/g,'');html=html.replace(/<input id="search"[^>]*>/g,'<span>Archivio personale · demo</span>');if(state.role==='home'){html=html.replace('</select>','</select><button class="v5-mobile-menu" aria-expanded="'+!!V5.mobileMenu+'" data-action="v5:mobile-nav">'+(V5.mobileMenu?'Chiudi menu':'Menu completo')+'</button>');if(V5.mobileMenu)html=html.replace('class="sidebar"','class="sidebar expanded"');html+='<nav class="v5-bottom" aria-label="Navigazione mobile">'+['Casa','Attività','Documenti','Spese'].map(p=>'<button class="'+(p===state.page?'active':'')+'" data-action="nav:'+p+'">'+p+'</button>').join('')+'</nav>';}html=html.replace('Simulazione promozionale basata sulla V5 consolidata e sul catalogo Home/Partner. Le funzioni mostrate possono essere concept; non attestano disponibilità commerciale o conformità.','Home allineata ai percorsi V5 del 24 ottobre 2026 · Dati e operazioni simulati. Partner e anteprime sono concept distinti.');html=html.replace('<div class="workspace">',`<div class="workspace v5-home">`);if(state.role==='home')html=html.replace('<div class="nav-extra">Altri percorsi della casa</div>','<div class="nav-extra">Altri percorsi della casa</div>');return html;};
// Draft editing follows the same progression as V5: document, objects, expenses,
// contacts and save. Switching to the single-page view retains the same draft.
function vCompile(id,mode='manual'){const doc=V5.documents.find(d=>d.id===id);if(!doc)return;const bill=id==='bill'||doc.family==='Utenze e servizi',plan=id==='plan'||doc.family==='Catasto e pratiche edilizie';const existing=doc.values,linked=V5.objects.find(o=>o.doc===id),cost=V5.expenses.find(e=>e.doc===id);V5.form={id,mode,step:0,single:false,showOriginal:true,values:existing?{...existing}:{name:doc.name,family:bill?'Utenze e servizi':plan?'Catasto e pratiche edilizie':'Acquisti, garanzie e manuali',date:'2026-10-24',object:bill||plan?'':linked?.name||(id==='purchase'?'Macchina da caffè':''),room:linked?.room||'Cucina',brand:linked?.brand||'',amount:cost?String(cost.amount):bill?'86.40':id==='purchase'?'499':'',expense:!!cost||bill||id==='purchase',supplier:cost?.supplier||(bill?'Fornitore Demo':'Rivenditore Demo'),objectAction:'Crea nuovo oggetto',target:'Lavastoviglie',contact:false,contactName:'Rivenditore Demo',email:'rivenditore@example.test',only:false},saved:doc.status==='Completato'};vEditor();}
function vReadDraft(){const f=V5.form;if(!f)return;$('#modal').querySelectorAll('[data-draft]').forEach(el=>{f.values[el.dataset.draft]=el.type==='checkbox'?el.checked:el.value;});}
function vDraftInput(label,key,type='text'){const value=V5.form.values[key];return type==='checkbox'?`<label class="check"><input type="checkbox" data-draft="${key}" ${value?'checked':''}><span>${label}</span></label>`:`<label for="draft-${key}">${label}</label><input id="draft-${key}" data-draft="${key}" type="${type}" value="${esc(value)}">`;}
function vDraftSection(i){const f=V5.form,v=f.values,bill=f.id==='bill'||v.family==='Utenze e servizi',plan=f.id==='plan';switch(i){case 5:return '<p>Questo esempio contiene un articolo. Scegli cosa conservare.</p><label for="draft-action">Cosa fare con l’articolo</label><select id="draft-action" data-draft="objectAction">'+vOptions(['Crea nuovo oggetto','Collega a un oggetto esistente','Escludi articolo'],v.objectAction||'Crea nuovo oggetto')+'</select><label for="draft-target">Oggetto esistente (se scegli Collega)</label><select id="draft-target" data-draft="target">'+vOptions(V5.objects.filter(o=>!o.archived).map(o=>o.name),v.target||'Lavastoviglie')+'</select><p class="tiny">La demo mostra un articolo; la V5 supporta anche documenti con più articoli.</p>';case 0:return vDraftInput('Nome del documento','name')+`<label for="draft-family">Famiglia</label><select id="draft-family" data-draft="family">${vOptions(FAMILIES,v.family)}</select>`+vDraftInput('Data del documento','date','date')+vDraftInput('Solo archiviazione del documento','only','checkbox');case 1:return bill||plan||v.only?'<p>Per questa scelta non viene creato alcun oggetto. Il documento resta nell’archivio della casa.</p>':vDraftInput('Nome oggetto','object')+vDraftInput('Marca (facoltativa)','brand')+`<label for="draft-room">Ambiente</label><select id="draft-room" data-draft="room">${vOptions(['Senza stanza',...V5.rooms],v.room)}</select><p class="tiny">Garanzia da verificare: non dedotta dall’acquisto.</p>`;case 2:return v.only||plan?'<p>La sola archiviazione non crea una spesa.</p>':vDraftInput('Registra una spesa collegata','expense','checkbox')+vDraftInput('Importo (€)','amount','number')+vDraftInput('Fornitore','supplier')+'<p class="tiny">Il pagamento non viene dedotto dalla fattura.</p>';case 3:return v.only?'<p>Nessun contatto creato.</p>':vDraftInput('Salva anche il contatto proposto nella Rubrica','contact','checkbox')+vDraftInput('Nome contatto','contactName')+vDraftInput('Email (esempio)','email','email')+'<p class="tiny">Scelta separata: la proposta non aggiunge automaticamente persone alla Rubrica.</p>';case 4:return `<div class="v5-summary"><p><strong>Documento:</strong> ${esc(v.name)}<br><strong>Famiglia:</strong> ${esc(v.family)}<br><strong>Oggetto:</strong> ${esc(!v.only&&!bill&&!plan&&v.objectAction!=='Escludi articolo'?(v.objectAction==='Collega a un oggetto esistente'?v.target:v.object):'Nessuno')}<br><strong>Spesa:</strong> ${!v.only&&!plan&&v.expense&&v.objectAction!=='Escludi articolo'?money(Number(v.amount)||0):'Non creare'}<br><strong>Contatto:</strong> ${!v.only&&v.contact?esc(v.contactName):'Non salvare'}</p></div><p>Controlla i dati. Il salvataggio aggiorna solo questa demo.</p>`;}}
function vFlow(){const f=V5.form,v=f.values;if(v.only||f.id==='plan')return [{title:'Documento',section:0},{title:'Riepilogo',section:4}];if(f.id==='bill'||v.family==='Utenze e servizi')return [{title:'Documento',section:0},{title:'Spese',section:2},{title:'Contatti',section:3},{title:'Riepilogo',section:4}];return [{title:'Documento',section:0},{title:'Contenuto',section:5},{title:'Articolo 1',section:1},{title:'Spese',section:2},{title:'Contatti',section:3},{title:'Riepilogo',section:4}];}
function vEditor(){const f=V5.form,d=V5.documents.find(x=>x.id===f.id),flow=vFlow(),titles=flow.map(s=>s.title);f.step=Math.min(f.step,flow.length-1);let sections=f.single?titles.map((t,i)=>`<section><h3>${i+1}. ${t}</h3>${vDraftSection(flow[i].section)}</section>`).join(''):`<section><h3>${titles[f.step]}</h3>${vDraftSection(flow[f.step].section)}</section>`;vModal('Completa i dati del documento',`<div class="v5-editor-actions">${vButton('Torna a Documenti','editor-leave',true)}${vButton(f.single?'Usa la compilazione a schede':'Torna alla pagina unica','editor-toggle',true)}${vButton(f.showOriginal?'Chiudi anteprima':'Apri anteprima','editor-preview',true)}</div><p>${esc(d.name)} · ${f.mode==='ai'?'Proposta AI simulata':'Compilazione manuale'}${f.saved?' · dati già salvati':''}</p>${!f.single?`<nav class="v5-steps" aria-label="Passaggi della compilazione">${titles.map((t,i)=>`<button ${i>f.step?'disabled':''} aria-current="${i===f.step?'step':'false'}" data-action="v5:editor-step:${i}">${i+1}. ${t}</button>`).join('')}</nav>`:''}<div class="v5-mobile-views">${vButton('Compila','editor-mobile-form',true)}${vButton('Originale','editor-mobile-original',true)}</div><div class="v5-editor-grid ${f.mobileOriginal?'mobile-original':''} ${f.showOriginal?'':'no-preview'}"><div>${sections}</div>${f.showOriginal?`<aside><h3>Originale</h3>${vFixtureDocument(d)}</aside>`:''}</div><p class="tiny">Un documento alla volta. Nessun file o dato viene inviato a servizi esterni in questa demo.</p>`,`${!f.single&&f.step>0?vButton('Indietro','editor-prev',true):''}${!f.single&&f.step<flow.length-1?vButton('Continua →','editor-next'):vButton('Salva nella demo','editor-save')}${vButton('Decidi più avanti','editor-pause',true)}${f.mode==='manual'?vButton('Precompila con AI · demo','editor-ai',true):''}`);$('#dialog').classList.add('v5-wide');}
function vValidateDraft(){const v=V5.form.values;if(!v.name.trim())return 'Indica il nome del documento.';if(!v.date)return 'Indica la data del documento.';if(!v.only&&v.expense&&v.objectAction!=='Escludi articolo'&&(v.amount===''||!Number.isFinite(Number(v.amount))||Number(v.amount)<0))return 'Controlla l’importo della spesa.';if(v.contact&&!v.only&&(!v.contactName.trim()||!/^\S+@\S+\.\S+$/.test(v.email)))return 'Controlla nome e indirizzo del contatto.';return '';}
function vSaveDraft(){vReadDraft();const problem=vValidateDraft();if(problem){vError(problem);return false}const f=V5.form,v=f.values,d=V5.documents.find(x=>x.id===f.id),bill=f.id==='bill'||v.family==='Utenze e servizi',plan=f.id==='plan';d.name=v.name;d.family=v.family;d.status='Completato';d.values={...v};let object=V5.objects.find(o=>o.doc===d.id);if(!v.only&&!bill&&!plan&&v.objectAction!=='Escludi articolo'&&v.object.trim()){if(v.objectAction==='Collega a un oggetto esistente'){object=V5.objects.find(o=>o.name===v.target);if(object)d.object=object.name;}else if(!object){object={id:vId(),name:v.object,brand:v.brand,model:'Da completare',room:v.room==='Senza stanza'?'':v.room,type:'Elettrodomestico',archived:false,warranty:'Da verificare',doc:d.id,cost:0};V5.objects.push(object);}else{object.name=v.object;object.brand=v.brand;object.room=v.room==='Senza stanza'?'':v.room;}d.object=object.name;object.documents=[...new Set([...(object.documents||[object.doc]).filter(Boolean),d.id])];}if(!v.only&&!plan&&v.expense&&v.objectAction!=='Escludi articolo'){let exp=V5.expenses.find(e=>e.doc===d.id);const data={name:bill?'Fornitura luce':v.object||v.name,amount:Number(v.amount),date:v.date,supplier:v.supplier,object:object?.id||'',doc:d.id,paid:false,work:''};if(exp)Object.assign(exp,data);else V5.expenses.push({id:vId(),...data});}if(!v.only&&v.contact&&!V5.contacts.some(c=>c.email===v.email))V5.contacts.push({id:vId(),name:v.contactName,email:v.email,role:v.supplier||'Professionista',archived:false});if(!V5.history.some(e=>e.doc===d.id))V5.history.push({id:vId(),title:v.only?'Documento archiviato: '+v.name:bill?'Spesa della casa registrata':v.object||v.name,date:v.date,doc:d.id,kind:object?'Oggetto aggiunto':'Documento'});V5.form=null;$('#dialog').classList.remove('v5-wide');close();state.reviewed=true;go('home','Documenti');toast('Documento salvato nella demo. Originale e collegamenti conservati.');return true;}
function vImport(){vModal('Aggiungi documento','<p>Come nell’app: aggiungi PDF o foto, poi completa i dati del documento. Qui usi solo esempi pronti.</p><label for="v5-sample">Documento di esempio</label><select id="v5-sample"><option value="purchase">Fattura acquisto demo</option><option value="bill">Bolletta luce demo</option><option value="plan">Planimetria della casa</option><option value="photo">Foto libretto demo</option></select><p class="tiny">PDF testuali: possibili proposte locali. Foto e scansioni: nessuna lettura automatica garantita. Nessun file personale viene caricato.</p>',vButton('Carica esempio e compila','import-done')+vButton('Scatta una foto · demo','photo',true));}
function vForm(kind,id=''){let body='',title='',action='';if(kind==='expense'){const e=V5.expenses.find(x=>x.id===id)||{};title=id?'Modifica spesa':'Registra una spesa';body=vField('Descrizione','v5-name',e.name||'')+vField('Importo (€)','v5-amount',e.amount??'','number')+vField('Data','v5-date',e.date||'2026-10-24','date')+vField('Fornitore','v5-supplier',e.supplier||'')+vSelect('Oggetto','v5-object',['Spesa della casa',...V5.objects.filter(o=>!o.archived).map(o=>o.name)],V5.objects.find(o=>o.id===e.object)?.name||'Spesa della casa')+vSelect('Lavoro','v5-work',['Nessuno',...V5.works.map(w=>w.name)],V5.works.find(w=>w.id===e.work)?.name||'Nessuno')+`<label class="check"><input type="checkbox" id="v5-paid" ${e.paid?'checked':''}><span>Pagamento dichiarato</span></label>`;action='expense-save:'+id;}if(kind==='task'){title='Nuova attività';body=vField('Nome attività','v5-name')+vField('Data','v5-date','2026-11-10','date')+vSelect('Oggetto','v5-object',['Casa',...V5.objects.filter(o=>!o.archived).map(o=>o.name)],V5.objects.find(o=>o.id===id)?.name||'Casa');action='task-save';}if(kind==='object'){const o=V5.objects.find(x=>x.id===id)||{};title=o.id?'Nome e tipo':'Aggiungi oggetto';body=vField('Nome','v5-name',o.name||'')+vField('Marca','v5-brand',o.brand||'')+vField('Modello','v5-model',o.model||'')+vSelect('Tipo','v5-type',['Elettrodomestico','Impianto','Arredo','Altro'],o.type||'Altro')+vSelect('Ambiente','v5-placement',['Senza stanza',...V5.rooms],o.room||'Senza stanza');action='object-save:'+id;}if(kind==='contact'){const c=V5.contacts.find(x=>x.id===id)||{};title=id?'Modifica contatto':'Nuovo contatto';body=vField('Nome','v5-name',c.name||'')+vField('Email','v5-email',c.email||'','email')+vField('Ruolo o attività','v5-role',c.role||'');action='contact-save:'+id;}if(kind==='event'){title='Aggiungi un evento';body=vField('Titolo','v5-name')+vField('Data','v5-date','2026-10-24','date')+vSelect('Documento collegato','v5-doc',['Nessuno',...V5.documents.map(d=>d.name)],V5.documents.find(d=>d.id===id)?.name||'Nessuno');action='event-save';}vModal(title,body,vButton('Salva nella demo',action)+vButton('Annulla','close',true));}
function vSharing(){vModal('Nuova condivisione','<p>Seleziona gli originali e verifica di avere i diritti per condividerli. Dati personali e Rubrica restano esclusi.</p>'+V5.documents.filter(d=>d.status==='Completato').map(d=>`<label class="check"><input type="checkbox" data-share="${d.id}"><span>${esc(d.name)}<small>Originale v1</small></span></label>`).join('')+vField('Email destinatario (fittizia)','v5-email','','email')+'<label class="check"><input type="checkbox" id="v5-rights"><span>Ho controllato documenti e diritti nella demo.</span></label>',vButton('Rivedi consegna','sharing-preview'));}
// Capture only Home simulation actions; legacy Partner interactions remain intact.
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;let action=el.dataset.action;if(action==='close'&&V5.form){e.stopImmediatePropagation();vReadDraft();vModal('Lasciare la compilazione?','<p>Le modifiche non salvate verranno scartate.</p>',vButton('Continua a compilare','editor-return')+vButton('Scarta e torna a Documenti','editor-discard',true));return}if(!action.startsWith('v5:')){if(action.startsWith('nav:'))V5.mobileMenu=false;if(state.role==='home'&&['import','review','demo:import'].includes(action)){e.stopImmediatePropagation();if(action==='demo:import')go('home','Documenti');vImport();}return}e.stopImmediatePropagation();const [a,...args]=action.slice(3).split(':'),id=args.join(':');switch(a){
case'mobile-nav':V5.mobileMenu=!V5.mobileMenu;render();break;case'close':V5.form=null;$('#dialog').classList.remove('v5-wide');close();break;
case'tab':V5[args[0]]=args[1];render();break;
case'import':vImport();break;
case'photo':vModal('Scatta una foto','<p>Nell’app puoi usare la fotocamera del telefono. In questa demo viene aggiunta una foto sintetica del libretto, senza attivare la fotocamera.</p><p>Una foto non avvia la lettura locale prevista per i PDF testuali.</p>',vButton('Usa foto di esempio','photo-done'));break;
case'photo-done':if(!V5.documents.some(d=>d.id==='photo'))V5.documents.push({id:'photo',name:'Foto libretto demo',family:'Energia e impianti',status:'Da compilare',object:'',personal:true});vCompile('photo');V5.form.values.object='';V5.form.values.expense=false;V5.form.values.amount='';vEditor();break;
case'import-done':{const selected=$('#v5-sample').value;if(selected==='photo'){el.dataset.action='v5:photo-done';el.click();break}vCompile(selected);break}
case'next-pending':{const d=V5.documents.find(x=>x.status!=='Completato');if(d)vCompile(d.id);else toast('Tutti i documenti di questa demo sono completati.');break}
case'compile':vCompile(id);break;case'document':vDocument(id);break;
case'editor-next':vReadDraft();V5.form.step=Math.min(vFlow().length-1,V5.form.step+1);vEditor();break;
case'editor-prev':vReadDraft();V5.form.step=Math.max(0,V5.form.step-1);vEditor();break;
case'editor-step':vReadDraft();V5.form.step=Number(id);vEditor();break;
case'editor-toggle':vReadDraft();V5.form.single=!V5.form.single;vEditor();break;
case'editor-mobile-form':vReadDraft();V5.form.mobileOriginal=false;vEditor();break;case'editor-mobile-original':vReadDraft();V5.form.mobileOriginal=true;V5.form.showOriginal=true;vEditor();break;case'editor-preview':vReadDraft();V5.form.showOriginal=!V5.form.showOriginal;vEditor();break;
case'editor-save':vSaveDraft();break;
case'editor-pause':vReadDraft();{const f=V5.form;V5.documents.find(d=>d.id===f.id).values={...f.values};}V5.form=null;$('#dialog').classList.remove('v5-wide');close();go('home','Documenti');toast('Bozza conservata nella sessione demo. Nessun oggetto o costo creato.');break;
case'editor-leave':vReadDraft();vModal('Lasciare la compilazione?','<p>Le modifiche non salvate verranno scartate.</p>',vButton('Continua a compilare','editor-return')+vButton('Scarta e torna a Documenti','editor-discard',true));break;
case'editor-return':vEditor();break;
case'editor-discard':V5.form=null;$('#dialog').classList.remove('v5-wide');close();go('home','Documenti');break;
case'editor-ai':vReadDraft();vModal('Precompila con AI · simulazione','<p>Nell’app serve un consenso separato per inviare questo documento al servizio AI; disponibilità e budget dipendono dall’ambiente.</p><p>Qui vengono mostrate proposte già preparate: nessun invio o costo.</p><label class="check"><input id="v5-ai-consent" type="checkbox"><span>Voglio esplorare la proposta AI dimostrativa.</span></label>',vButton('Mostra proposta simulata','ai-consent')+vButton('Continua manualmente','editor-return',true));break;
case'ai-consent':if(!$('#v5-ai-consent').checked){vError('Conferma la scelta dimostrativa per continuare.');break}V5.form.mode='ai';vEditor();break;
case'analysis':{const d=V5.documents.find(x=>x.status!=='Completato')||V5.documents[0];vCompile(d.id);vReadDraft();vModal('Proposta AI dimostrativa','<p>Il documento selezionato è '+esc(d.name)+'. Nessun invio verrà effettuato.</p><label class="check"><input id="v5-ai-consent" type="checkbox"><span>Voglio esplorare la proposta AI dimostrativa.</span></label>',vButton('Mostra proposta simulata','ai-consent'));break}
case'download':{const d=V5.documents.find(x=>x.id===id),url=URL.createObjectURL(new Blob(['FACSIMILE DIMOSTRATIVO\n'+d.name+'\nNessun originale personale.'],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='dimora-facsimile-demo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}
case'family':{const d=V5.documents.find(x=>x.id===id);vModal('Cambia famiglia',vSelect('Famiglia','v5-new-family',FAMILIES,d.family)+'<p>I collegamenti del documento rimangono.</p>',vButton('Conferma nella demo','family-save:'+id));break}
case'family-save':V5.documents.find(x=>x.id===id).family=$('#v5-new-family').value;close();render();break;
case'delete':{const linked=V5.objects.some(o=>o.doc===id||o.documents?.includes(id))||V5.expenses.some(x=>x.doc===id)||V5.history.some(x=>x.doc===id);vModal(linked?'Documento collegato':'Elimina documento',linked?'<p>Questo originale è usato da oggetti, spese o storia. Nella demo viene mantenuto: prima vanno riesaminati i collegamenti, come nell’app.</p>':'<p>Il documento non ha collegamenti. Vuoi rimuovere questo esempio dalla sessione?</p>',linked?vButton('Torna al documento','document:'+id,true):vButton('Elimina esempio','delete-confirm:'+id));break}
case'delete-confirm':V5.documents=V5.documents.filter(d=>d.id!==id);close();render();toast('Solo l’esempio di questa sessione è stato eliminato.');break;
case'object':vObject(id);break;case'object-new':vForm('object');if(id)$('#v5-placement').value=id;break;case'object-edit':vForm('object',id);break;
case'object-save':{const name=$('#v5-name').value.trim();if(!name){vError('Indica il nome dell’oggetto.');break}const old=V5.objects.find(o=>o.id===id),data={name,brand:$('#v5-brand').value,model:$('#v5-model').value,type:$('#v5-type').value,room:$('#v5-placement').value==='Senza stanza'?'':$('#v5-placement').value};if(old)Object.assign(old,data);else V5.objects.push({id:vId(),...data,archived:false,warranty:'Da verificare',doc:'',cost:0});close();render();break}
case'object-archive':{const o=V5.objects.find(x=>x.id===id);vModal(o.archived?'Ripristina oggetto':'Archivia oggetto','<p>Documenti, spese e collegamenti restano. L’oggetto cambia solo stato.</p>',vButton('Conferma nella demo','object-archive-confirm:'+id));break}
case'object-archive-confirm':{const o=V5.objects.find(x=>x.id===id);o.archived=!o.archived;close();render();break}
case'placement':vModal('Dove si trova',vSelect('Ambiente','v5-placement',['Senza stanza',...V5.rooms],V5.objects.find(o=>o.id===id).room||'Senza stanza'),vButton('Salva posizione','placement-save:'+id));break;
case'placement-save':V5.objects.find(o=>o.id===id).room=$('#v5-placement').value==='Senza stanza'?'':$('#v5-placement').value;vObject(id);break;
case'warranty':{const o=V5.objects.find(x=>x.id===id);vModal('Dati e garanzia','<p>Non dedurre la copertura dal solo acquisto. Riporta ciò che hai verificato sul documento.</p>'+vSelect('Stato','v5-warranty',['Da verificare','Garanzia dichiarata'],o.warranty==='Da verificare'?'Da verificare':'Garanzia dichiarata')+vField('Fine garanzia dichiarata','v5-warranty-end','','date'),vButton('Salva nella demo','warranty-save:'+id));break}
case'warranty-save':{const status=$('#v5-warranty').value,end=$('#v5-warranty-end').value;if(status==='Garanzia dichiarata'&&!end){vError('Indica la data che hai verificato oppure lascia Da verificare.');break}V5.objects.find(o=>o.id===id).warranty=status==='Da verificare'?status:status+' · '+vDate(end);vObject(id);break}
case'room':vRoom(id);break;
case'room-new':case'room-edit':vModal(a==='room-new'?'Aggiungi ambiente':'Modifica ambiente',vField('Nome ambiente','v5-name',id),vButton('Salva nella demo','room-save:'+id));break;
case'room-save':{const n=$('#v5-name').value.trim();if(!n){vError('Indica il nome dell’ambiente.');break}if(V5.rooms.includes(n)&&n!==id){vError('Esiste già un ambiente con questo nome.');break}if(id){V5.rooms=V5.rooms.map(r=>r===id?n:r);V5.objects.forEach(o=>{if(o.room===id)o.room=n;});}else V5.rooms.push(n);close();render();break}
case'floorplan':vModal('Ambienti da planimetria','<p>Come nel percorso V5: scegli il documento, rivedi la proposta degli ambienti e conferma. Qui esplori un esempio già preparato.</p><label class="check"><input id="v5-floor-room" type="checkbox" checked><span>Studio · ambiente proposto</span></label><p>Nessuna superficie o conformità dedotta.</p>',vButton('Conferma ambiente demo','floorplan-save'));break;
case'floorplan-save':if($('#v5-floor-room').checked&&!V5.rooms.includes('Studio'))V5.rooms.push('Studio');close();render();break;
case'task':vTask(id);break;case'task-new':vForm('task',id);break;
case'task-save':{const name=$('#v5-name').value.trim(),date=$('#v5-date').value;if(!name||!date){vError('Indica nome e data dell’attività.');break}const object=V5.objects.find(o=>o.name===$('#v5-object').value)?.id||'';V5.tasks.push({id:vId(),name,date,object,done:false,next:''});close();render();break}
case'task-done':{const date=$('#v5-completed').value,next=$('#v5-next').value;if(!date||next&&next<=date){vError('Controlla la data completamento e scegli un promemoria successivo.');break}const t=V5.tasks.find(x=>x.id===id);t.done=true;t.next=next;if(next)V5.tasks.push({id:vId(),name:t.name,date:next,object:t.object,done:false,next:''});V5.history.push({id:vId(),title:t.name,date,doc:'',kind:'Attività completata'});close();render();toast('Attività completata nella demo'+(next?' e nuovo promemoria creato.':'.'));break}
case'expense-new':vForm('expense');break;case'expense-edit':vForm('expense',id);break;case'expense':vExpense(id);break;
case'expense-save':{const name=$('#v5-name').value.trim(),amount=Number($('#v5-amount').value),date=$('#v5-date').value;if(!name||$('#v5-amount').value===''||!Number.isFinite(amount)||amount<0||!date){vError('Controlla descrizione, importo e data.');break}const old=V5.expenses.find(x=>x.id===id),data={name,amount,date,supplier:$('#v5-supplier').value,object:V5.objects.find(o=>o.name===$('#v5-object').value)?.id||'',paid:$('#v5-paid').checked,work:V5.works.find(w=>w.name===$('#v5-work').value)?.id||''};if(old)Object.assign(old,data);else V5.expenses.push({id:vId(),...data,doc:''});close();render();break}
case'object-expenses':{const o=V5.objects.find(x=>x.id===id);vModal('Spese · '+o.name,V5.expenses.filter(e=>e.object===id).map(e=>vRow(e.name,money(e.amount),'expense:'+e.id)).join('')||'<p>Nessuna spesa collegata.</p>',vButton('Registra una spesa','expense-new'));break}
case'works':vModal('Lavori','<p>Raggruppa le spese per un intervento della casa.</p>'+V5.works.map(w=>vRow(w.name,'Lavoro dimostrativo','work:'+w.id)).join('')+vField('Nome del nuovo lavoro','v5-name'),vButton('Aggiungi lavoro demo','work-save'));break;
case'work-save':{const n=$('#v5-name').value.trim();if(!n){vError('Indica il nome del lavoro.');break}V5.works.push({id:vId(),name:n});close();toast('Lavoro aggiunto alla demo.');break}
case'work':vModal(V5.works.find(w=>w.id===id).name,'<p>Spese collegate a questo lavoro:</p>'+ (V5.expenses.filter(e=>e.work===id).map(e=>vRow(e.name,money(e.amount),'expense:'+e.id)).join('')||'<p>Nessuna spesa ancora collegata.</p>'),vButton('Registra una spesa','expense-new'));break;
case'contacts':close();go('home','Rubrica');break;case'contact':vContact(id);break;case'contact-new':vForm('contact');break;case'contact-edit':vForm('contact',id);break;
case'contact-save':{const name=$('#v5-name').value.trim(),email=$('#v5-email').value;if(!name||email&&!$('#v5-email').checkValidity()){vError('Controlla nome e indirizzo email.');break}const data={name,email,role:$('#v5-role').value},old=V5.contacts.find(x=>x.id===id);if(old)Object.assign(old,data);else V5.contacts.push({id:vId(),...data,archived:false});close();render();break}
case'contact-archive':{const c=V5.contacts.find(x=>x.id===id);c.archived=!c.archived;close();render();toast('Stato del contatto aggiornato nella demo.');break}
case'contact-links':{const c=V5.contacts.find(x=>x.id===id);vModal('Collegamenti · '+c.name,V5.expenses.filter(e=>e.supplier===c.name).map(e=>vRow(e.name,'Spesa · '+money(e.amount),'expense:'+e.id)).join('')||'<p>Nessun collegamento per questo contatto.</p>');break}
case'event':vForm('event',id);break;
case'event-save':{const title=$('#v5-name').value.trim(),date=$('#v5-date').value;if(!title||!date){vError('Indica titolo e data dell’evento.');break}V5.history.push({id:vId(),title,date,doc:V5.documents.find(d=>d.name===$('#v5-doc').value)?.id||'',kind:'Evento personale'});close();render();break}
case'event-detail':{const ev=V5.history.find(x=>x.id===id);vModal(ev.title,'<p>'+vDate(ev.date)+' · '+ev.kind+'</p>');break}
case'sharing':vSharing();break;
case'sharing-preview':{const selected=[...$('#modal').querySelectorAll('[data-share]:checked')].map(x=>x.dataset.share),email=$('#v5-email').value;if(!selected.length||!email||!$('#v5-email').checkValidity()||!$('#v5-rights').checked){vError('Seleziona almeno un documento, un destinatario valido e conferma i diritti.');break}V5.pendingShare={id:vId(),email,names:selected.map(id=>V5.documents.find(d=>d.id===id).name),status:'In attesa di accettazione · simulata'};vModal('Riepilogo della consegna','<p>Destinatario: '+esc(email)+'</p><p>Documenti: '+V5.pendingShare.names.map(esc).join(' · ')+'</p><p>Originali v1. Rubrica e dati personali non selezionati restano esclusi.</p><p class="tiny">Nessun invio o trasferimento reale.</p>',vButton('Prepara consegna demo','sharing-save'));break}
case'sharing-save':V5.shares.push(V5.pendingShare);V5.pendingShare=null;close();render();break;
case'share-detail':{const s=V5.shares.find(x=>x.id===id);vModal('Consegna · '+s.email,'<p>'+esc(s.status)+'</p><p>'+s.names.map(esc).join(' · ')+'</p>',vButton('Revoca nella demo','share-revoke:'+id,true));break}
case'share-revoke':V5.shares.find(x=>x.id===id).status='Revocata · simulata';close();render();break;
}},true);
const vSearchKeys={'v5-doc-search':'query','v5-object-search':'objectQuery','v5-room-search':'roomQuery','v5-contact-search':'contactQuery','v5-expense-search':'expenseQuery'};
document.addEventListener('input',e=>{const key=vSearchKeys[e.target.id];if(!key)return;const id=e.target.id,pos=e.target.selectionStart;V5[key]=e.target.value;render();const field=$('#'+id);field.focus();field.setSelectionRange(pos,pos);});
document.addEventListener('change',e=>{const map={'v5-family':'family','v5-room-filter':'room','v5-object-state':'objectState'};if(map[e.target.id]){V5[map[e.target.id]]=e.target.value;render();}});
$('#dialog').addEventListener('cancel',e=>{if(V5.form){e.preventDefault();vReadDraft();vModal('Lasciare la compilazione?','<p>Le modifiche non salvate verranno scartate.</p>',vButton('Continua a compilare','editor-return')+vButton('Scarta e torna a Documenti','editor-discard',true));}});
// The first original route render runs before this file; replace it once overrides exist.
render();
